CREATE TABLE IF NOT EXISTS `PREFIX_cm_carrier_accounts` (`id` INT AUTO_INCREMENT NOT NULL, `carrier_code` VARCHAR(50) NOT NULL, `display_name` VARCHAR(100) NOT NULL, `api_id` VARCHAR(255) DEFAULT NULL, `api_token` VARCHAR(255) DEFAULT NULL, `webhook_secret` VARCHAR(255) DEFAULT NULL, `extra_config` TEXT DEFAULT NULL, `is_default` TINYINT(1) NOT NULL DEFAULT 0, `is_active` TINYINT(1) NOT NULL DEFAULT 1, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_carrier_code` (`carrier_code`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `PREFIX_cm_parcels` (`id` INT AUTO_INCREMENT NOT NULL, `order_id` INT UNSIGNED NOT NULL, `carrier_account_id` INT DEFAULT NULL, `tracking` VARCHAR(100) DEFAULT NULL, `import_id` BIGINT UNSIGNED DEFAULT NULL, `label_url` VARCHAR(500) DEFAULT NULL, `delivery_type` VARCHAR(50) DEFAULT NULL, `is_economic` TINYINT(1) NOT NULL DEFAULT 0, `wilaya_id` INT UNSIGNED DEFAULT NULL, `wilaya_name` VARCHAR(100) DEFAULT NULL, `commune_id` INT UNSIGNED DEFAULT NULL, `commune_name` VARCHAR(100) DEFAULT NULL, `center_id` INT UNSIGNED DEFAULT NULL, `center_name` VARCHAR(100) DEFAULT NULL, `phone` VARCHAR(20) DEFAULT NULL, `delivery_fee` INT UNSIGNED NOT NULL DEFAULT 0, `freeshipping` TINYINT(1) NOT NULL DEFAULT 0, `price` INT UNSIGNED NOT NULL DEFAULT 0, `weight` DECIMAL(8,3) NOT NULL DEFAULT 0, `status` VARCHAR(100) NOT NULL DEFAULT 'confirmed', `status_changed_at` DATETIME DEFAULT NULL, `shipped_at` DATETIME DEFAULT NULL, `delivered_at` DATETIME DEFAULT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (`id`), UNIQUE KEY `uk_tracking` (`tracking`), KEY `idx_order_id` (`order_id`), KEY `idx_carrier_account_id` (`carrier_account_id`), KEY `idx_status` (`status`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS `PREFIX_cm_parcel_histories` (`id` INT AUTO_INCREMENT NOT NULL, `parcel_id` INT NOT NULL, `status` VARCHAR(100) NOT NULL, `reason` TEXT DEFAULT NULL, `raw_payload` TEXT DEFAULT NULL, `occurred_at` DATETIME NOT NULL, `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (`id`), KEY `idx_parcel_id` (`parcel_id`), CONSTRAINT `fk_cm_history_parcel` FOREIGN KEY (`parcel_id`) REFERENCES `PREFIX_cm_parcels` (`id`) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
